public static class CandyWorldBuilder {
 const string Root="Assets/ReinoDeChicle/";const string Base="Assets/Prototype_CoopBeam/";
 static Material mat;static Sprite dot;static Sprite[] surfaces;static EnemyBase[] prefabs;
 public static readonly string[] Titles={"PRADERAS DE CARAMELO","BOSQUE DE GOMITAS","FÁBRICA DE DULCES","FORTALEZA DE NUBE Y CACAO","TRONO DEL REY BURBUJA"};
 static readonly string[] Lessons={"Rodeen a los caramelos y conecten el lazo.\nPrueben a atravesar varios enemigos a la vez.","Las gomitas verdes los impulsan al aterrizar.\nUno abajo y otro arriba: ¡busquen la diagonal!","Las cintas desplazan y las islas se mueven.\nAmarillo avisa; rojo aplasta. Busquen otra ruta.","Los malvaviscos tiemblan antes de deshacerse.\nVuelven en unos segundos. Conserven una salida.","El Rey Burbuja protege su cuerpo.\nEsquiven las perlas y crucen el núcleo de menta\ncuando brille. Cambia de altura en cada fase."};
 [MenuItem("Coop Beam/Build Candy World")]
 public static void Build(){if(EditorApplication.isPlaying)throw new Exception("Exit Play mode first");if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Save current scene first");
 foreach(var folder in new[]{"0_0_Scenes","0_1_Scripts","0_2_Prefabs","0_3_Art","0_4_Editor","0_5_Documentation","0_6_QA","0_7_LevelData"})Directory.CreateDirectory(Root+folder);
 AssetDatabase.Refresh();mat=AssetDatabase.LoadAssetAtPath<Material>(Base+"0_3_Art/SpriteUnlit.mat");dot=AssetDatabase.LoadAssetAtPath<Sprite>(Base+"0_3_Art/mote.png");
 surfaces=new Sprite[5];for(int i=0;i<5;i++)surfaces[i]=PaintSurface(i);
 prefabs=new EnemyBase[7];for(int i=0;i<7;i++)prefabs[i]=CreateEnemy(i);
 for(int level=1;level<=5;level++)BuildLevel(level);
 var mapScene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);Camera();var map=new GameObject("Candy world selection").AddComponent<CandyWorldMap>();map.backdrop=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"0_3_Art/Background_01.png");EditorSceneManager.SaveScene(mapScene,Root+"0_0_Scenes/Candy_WorldMap.unity");
 var builds=new List<EditorBuildSettingsScene>(EditorBuildSettings.scenes);var paths=new List<string>{Root+"0_0_Scenes/Candy_WorldMap.unity",Base+"0_0_Scenes/Prototype_CoopBeam.unity"};for(int i=1;i<=5;i++)paths.Add(CandyCampaign.ScenePath(i));foreach(var path in paths)if(!builds.Exists(s=>s.path==path))builds.Add(new EditorBuildSettingsScene(path,true));EditorBuildSettings.scenes=builds.ToArray();
 AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(CandyCampaign.ScenePath(1));if(CandyPixelStyle.Available)CandyPixelStyle.Apply();Debug.Log("CANDY_WORLD_BUILD_OK: 5 levels, map, 7 enemies, progression and art.");}
 static void Camera(){var c=new GameObject("Candy Camera",typeof(UnityEngine.Camera),typeof(AudioListener)).GetComponent<UnityEngine.Camera>();c.tag="MainCamera";c.orthographic=true;c.orthographicSize=7.5f;c.transform.position=new Vector3(0,1,-10);c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=Hex("282242");c.gameObject.AddComponent<ArenaCamera>();}
 static void BuildLevel(int number){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);Camera();
 string backgroundPath=Root+"0_3_Art/Background_0"+number+".png";if(File.Exists(backgroundPath)){var imp=(TextureImporter)AssetImporter.GetAtPath(backgroundPath);imp.textureType=TextureImporterType.Sprite;imp.spritePixelsPerUnit=100;imp.mipmapEnabled=false;imp.SaveAndReimport();var bg=AssetDatabase.LoadAssetAtPath<Sprite>(backgroundPath);var image=Visual("Original candy backdrop",bg,new Vector2(0,1),Vector2.one,Color.white,-30);image.transform.localScale=new Vector3(26/bg.bounds.size.x,15/bg.bounds.size.y,1);}
 // Candy decorations occupy the margins and never hide combatants.
 for(int side=-1;side<=1;side+=2)for(int i=0;i<4;i++){Visual("Candy cane stem",surfaces[0],new Vector2(side*(10.6f-i*.12f),-2.8f+i*1.55f),new Vector2(.14f,2),Hex("FFF3DC"),-12);var sweet=Visual("Lollipop",dot,new Vector2(side*(10.6f-i*.12f),-1.8f+i*1.55f),new Vector2(1,1),Hex(i%2==0?"F8ADC7":"A9EBD7"),-11);sweet.transform.Rotate(0,0,i*30);}
 Platform("Chocolate foundation",new Vector2(0,-4.7f),new Vector2(23,.8f),3,false);
 if(number==1){Platform("Left caramel",new Vector2(-6,-2.1f),new Vector2(5,.45f),0);Platform("Right caramel",new Vector2(6,-2.1f),new Vector2(5,.45f),0);Platform("Sugar bridge",new Vector2(0,0),new Vector2(5,.45f),0);}
 if(number==2){Surface("Spring left",new Vector2(-6,-2.1f),new Vector2(4,.5f),CandySurfaceKind.Bounce,1);Surface("Spring right",new Vector2(6,-2.1f),new Vector2(4,.5f),CandySurfaceKind.Bounce,1);Platform("Gummy middle",new Vector2(0,.6f),new Vector2(5,.45f),1);Platform("High left",new Vector2(-6,2.8f),new Vector2(4,.45f),1);Platform("High right",new Vector2(6,2.8f),new Vector2(4,.45f),1);}
 if(number==3){Surface("Conveyor right",new Vector2(-6,-2.1f),new Vector2(5,.5f),CandySurfaceKind.Conveyor,4,1.8f);Surface("Conveyor left",new Vector2(6,-2.1f),new Vector2(5,.5f),CandySurfaceKind.Conveyor,4,-1.8f);Surface("Moving caramel lift",new Vector2(0,.2f),new Vector2(4,.45f),CandySurfaceKind.Moving,0);Platform("Upper machine left",new Vector2(-6,2.6f),new Vector2(4,.45f),3);Platform("Upper machine right",new Vector2(6,2.6f),new Vector2(4,.45f),3);Hazard(new Vector2(0,-3.3f),new Vector2(2,1.9f),0);}
 if(number==4){Surface("Crumbly left",new Vector2(-6,-2.1f),new Vector2(5,.55f),CandySurfaceKind.Crumbly,2);Surface("Crumbly right",new Vector2(6,-2.1f),new Vector2(5,.55f),CandySurfaceKind.Crumbly,2);Platform("Safe cocoa refuge",new Vector2(0,.2f),new Vector2(5,.5f),3);Surface("Upper marshmallow",new Vector2(-6,2.6f),new Vector2(4,.55f),CandySurfaceKind.Moving,2);Platform("Upper cocoa",new Vector2(6,2.6f),new Vector2(4,.5f),3);Hazard(new Vector2(-8.8f,-3.3f),new Vector2(1.5f,1.9f),0);Hazard(new Vector2(8.8f,-3.3f),new Vector2(1.5f,1.9f),2);}
 if(number==5){Platform("Royal left step",new Vector2(-7,-2.1f),new Vector2(4.5f,.5f),0);Platform("Royal right step",new Vector2(7,-2.1f),new Vector2(4.5f,.5f),0);Platform("Mint heart bridge",new Vector2(0,.3f),new Vector2(4,.5f),1);Platform("Left royal gallery",new Vector2(-6,2.6f),new Vector2(4,.45f),2);Platform("Right royal gallery",new Vector2(6,2.6f),new Vector2(4,.45f),2);}
 foreach(float x in new[]{-11.7f,11.7f}){var wall=new GameObject("Sugar arena boundary");wall.layer=8;wall.transform.position=new Vector2(x,1);wall.AddComponent<BoxCollider2D>().size=new Vector2(.5f,13);}
 var manager=new GameObject("Candy Level "+number).AddComponent<GameManager>();manager.enemyPrefabs=prefabs;manager.particle=dot;manager.level=LevelData(number);manager.players=new PlayerHealth[2];
 for(int i=0;i<2;i++){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Base+"0_2_Prefabs/"+(i==0?"Coral":"Celeste")+".prefab"));g.transform.position=new Vector2(i==0?-6:6,-3.7f);var h=g.GetComponent<PlayerHealth>();h.spawn=g.transform.position;manager.players[i]=h;PrefabUtility.RecordPrefabInstancePropertyModifications(h);PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);}
 var beam=new GameObject("Only weapon - Cooperative beam").AddComponent<CoopBeam.CoopBeam>();beam.red=manager.players[0];beam.blue=manager.players[1];beam.core=Line(beam.transform,"Core",.055f,7);beam.halo=Line(beam.transform,"Halo",.24f,6);beam.outline=Line(beam.transform,"Contrast edge",.13f,5);beam.outline.startColor=beam.outline.endColor=new Color(.16f,.1f,.3f,.85f);var ui=new GameObject("Candy HUD").AddComponent<UIManager>();ui.game=manager;
 EditorSceneManager.SaveScene(scene,CandyCampaign.ScenePath(number));}
 static CandyLevelDefinition LevelData(int n){string path=Root+"0_7_LevelData/Level_0"+n+".asset";var d=AssetDatabase.LoadAssetAtPath<CandyLevelDefinition>(path);if(!d){d=ScriptableObject.CreateInstance<CandyLevelDefinition>();AssetDatabase.CreateAsset(d,path);}d.number=n;d.title=Titles[n-1];d.lesson=Lessons[n-1];d.boss=n==5;
 int[][] kinds=n==1?new[]{new[]{0,0},new[]{0,0,1},new[]{0,1,0}}:n==2?new[]{new[]{1,4},new[]{0,1,4},new[]{1,4,4}}:n==3?new[]{new[]{0,5},new[]{1,5,2},new[]{2,4,5,0}}:n==4?new[]{new[]{3,1},new[]{2,4,1},new[]{3,5,4}}:new[]{new[]{0,4},new[]{1,2},new[]{6}};
 d.waves=new CandyWave[3];for(int w=0;w<3;w++){d.waves[w]=new CandyWave{enemyTypes=kinds[w],spawnPositions=new Vector2[kinds[w].Length]};for(int i=0;i<kinds[w].Length;i++){int kind=kinds[w][i];float x=kinds[w].Length==1?0:(i-(kinds[w].Length-1)*.5f)*4;float y=kind==4?2.9f:kind==6?-2.9f:w==0?-3.65f:i%2==0?-1.25f:1.1f;d.waves[w].spawnPositions[i]=new Vector2(x,y);}}
 EditorUtility.SetDirty(d);return d;}
 static EnemyBase CreateEnemy(int kind){string[] names={"CandyWalker","GummyJumper","ToffeeChaser","CocoaGuard","FlyingGummy","SugarCannon","KingBubble"};var g=new GameObject(names[kind]);g.layer=kind==6?12:10;
 var rb=g.AddComponent<Rigidbody2D>();rb.bodyType=kind==4||kind==6?RigidbodyType2D.Kinematic:RigidbodyType2D.Dynamic;rb.gravityScale=3;rb.freezeRotation=true;rb.interpolation=RigidbodyInterpolation2D.Interpolate;rb.collisionDetectionMode=CollisionDetectionMode2D.Continuous;
 var col=g.AddComponent<CapsuleCollider2D>();col.size=kind==6?new Vector2(2.5f,2.4f):kind==3?new Vector2(1.3f,1.3f):new Vector2(.85f,.95f);
 var art=Visual("Original candy creature",PaintCreature(kind),Vector2.zero,Vector2.one*(kind==6?3.4f:kind==3?1.65f:1.3f),Color.white,4);art.transform.SetParent(g.transform,false);
 var e=g.AddComponent<EnemyBase>();e.kind=(EnemyKind)kind;e.maxHealth=new[]{23,35,42,105,32,55,480}[kind];e.speed=new[]{1.35f,2.2f,3.3f,.8f,0,0,0}[kind];e.visual=art.transform;e.sprite=art.GetComponent<SpriteRenderer>();
 if(kind==4||kind==5){var special=g.AddComponent<CandyEnemySpecial>();special.projectile=dot;var aim=Visual("Charge indicator",dot,Vector2.up*.4f,Vector2.one*.15f,Hex("FFE78D"),6);aim.transform.SetParent(g.transform,false);special.telegraph=aim.transform;}
 if(kind==6){var boss=g.AddComponent<CandyBoss>();boss.projectile=dot;var weak=new GameObject("Only vulnerable collider - Mint core");weak.layer=10;weak.transform.SetParent(g.transform,false);weak.transform.localPosition=Vector3.up*.25f;var c=weak.AddComponent<CircleCollider2D>();c.radius=.65f;c.isTrigger=true;boss.weakSpot=c;var core=Visual("Glowing mint heart",dot,Vector2.up*.25f,Vector2.one*1.2f,Hex("B5FFCC"),6);core.transform.SetParent(g.transform,false);boss.weakArt=core.GetComponent<SpriteRenderer>();}
 var prefab=PrefabUtility.SaveAsPrefabAsset(g,Root+"0_2_Prefabs/"+names[kind]+".prefab");UnityEngine.Object.DestroyImmediate(g);return prefab.GetComponent<EnemyBase>();}
 static GameObject Platform(string name,Vector2 pos,Vector2 size,int surface,bool semi=true){var root=new GameObject(name);root.layer=semi?9:8;root.transform.position=pos;var c=root.AddComponent<BoxCollider2D>();c.size=size;if(semi){c.usedByEffector=true;var effect=root.AddComponent<PlatformEffector2D>();effect.useOneWay=true;effect.useOneWayGrouping=true;effect.surfaceArc=165;}var art=Visual("Candy platform art",surfaces[surface],Vector2.zero,size,Color.white,0);art.transform.SetParent(root.transform,false);return root;}
 static void Surface(string name,Vector2 pos,Vector2 size,CandySurfaceKind kind,int style,float strength=16){var root=Platform(name,pos,size,style);var env=root.AddComponent<CandyEnvironment>();env.kind=kind;env.strength=strength;env.art=root.transform.GetChild(0);if(kind==CandySurfaceKind.Moving){var b=root.AddComponent<Rigidbody2D>();b.bodyType=RigidbodyType2D.Kinematic;env.travel=1.4f;env.period=5;}}
 static void Hazard(Vector2 pos,Vector2 size,float offset){var root=new GameObject("Telegraphed sugar press");root.transform.position=pos;var h=root.AddComponent<CandyHazard>();h.area=size;h.phaseOffset=offset;var warning=Visual("Yellow warning - red danger",surfaces[0],Vector2.zero,size,new Color(1,.8f,.2f,.1f),2);warning.transform.SetParent(root.transform,false);h.warning=warning.GetComponent<SpriteRenderer>();var press=Visual("Animated press",surfaces[3],Vector2.up*2,new Vector2(size.x,.4f),Hex("DBA2CB"),3);press.transform.SetParent(root.transform,false);h.crusher=press.GetComponent<SpriteRenderer>();}
 static GameObject Visual(string name,Sprite sprite,Vector2 pos,Vector2 scale,Color color,int order){var g=new GameObject(name);g.transform.position=pos;g.transform.localScale=new Vector3(scale.x,scale.y,1);var r=g.AddComponent<SpriteRenderer>();r.sprite=sprite;r.sharedMaterial=mat;r.color=color;r.sortingOrder=order;return g;}
 static LineRenderer Line(Transform parent,string name,float width,int order){var g=new GameObject(name);g.transform.parent=parent;var l=g.AddComponent<LineRenderer>();l.sharedMaterial=mat;l.positionCount=2;l.widthMultiplier=width;l.numCapVertices=8;l.sortingOrder=order;return l;}
 static Color Hex(string hex){ColorUtility.TryParseHtmlString("#"+hex,out Color c);return c;}
 static Sprite SaveTexture(string name,Texture2D texture){string path=Root+"0_3_Art/"+name+".png";File.WriteAllBytes(path,texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(path);var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Sprite;i.spritePixelsPerUnit=256;i.alphaIsTransparency=true;i.mipmapEnabled=false;i.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
 static Sprite PaintSurface(int kind){int n=256;var t=new Texture2D(n,n,TextureFormat.RGBA32,false);var colors=new[]{Hex("EBA1BD"),Hex("81DDBB"),Hex("FFF0DB"),Hex("76516B"),Hex("C89C63")};for(int y=0;y<n;y++)for(int x=0;x<n;x++){Color c=colors[kind];if(x<4||x>251||y<10)c=Color.Lerp(c,Hex("302541"),.5f);else if(y>207+Mathf.Sin(x*.13f)*7)c=kind==3?Hex("B17B8D"):Hex("FFF5E6");else if(kind==4&&((x+y*2)%70)<15)c=Hex("76516B");else if(kind==3&&(x%64<4||y%80<4))c=Hex("523E53");else if(((x*17+y*37)%887)<7&&y>50)c=Hex("FFE18B");t.SetPixel(x,y,c);}t.Apply();return SaveTexture(new[]{"CaramelPlatform","GummyPlatform","MarshmallowPlatform","ChocolatePlatform","ConveyorPlatform"}[kind],t);}
 static Sprite PaintCreature(int kind){int n=256;var t=new Texture2D(n,n,TextureFormat.RGBA32,false);Color ink=Hex("372942"),color=Hex(new[]{"F6A5BE","95E5B2","FFCF83","A98294","C2AEFF","E4B47E","EF8EC5"}[kind]);for(int y=0;y<n;y++)for(int x=0;x<n;x++){float u=(x+.5f)/128-1,v=(y+.5f)/128-1;Color c=Color.clear;
  Func<float,float,float,float,bool> el=(a,b,rx,ry)=>Mathf.Pow((u-a)/rx,2)+Mathf.Pow((v-b)/ry,2)<1;
  bool body=el(0,-.16f,kind==6?.83f:.61f,.63f);bool extra=kind==0?el(-.67f,.05f,.24f,.28f)||el(.67f,.05f,.24f,.28f):kind==4?el(-.65f,.22f,.3f,.38f)||el(.65f,.22f,.3f,.38f):kind==6?v>.43f&&v<.78f&&Mathf.Abs(u)<.55f&&v<.75f-Mathf.Sin(u*19)*.12f:el(-.3f,.45f,.17f,.26f)||el(.3f,.45f,.17f,.26f);
  if(body||extra)c=ink;if(el(0,-.16f,kind==6?.77f:.55f,.57f))c=Color.Lerp(color,Color.white,Mathf.Clamp01((v+.6f)*.25f));if(extra&&v>.49f)c=kind==6?Hex("FFE07A"):color;
  if(kind==3&&body&&v>.1f)c=(Mathf.Abs(u*3)%1)<.12f?ink:Hex("8D6B82");
  if((kind==0||kind==2)&&body&&v<-.35f&&((u+v)*7%2)>1)c=Color.Lerp(color,Color.white,.5f);
  if(el(-.23f,.04f,.15f,.21f)||el(.23f,.04f,.15f,.21f))c=Color.white;if(el(-.2f,.01f,.075f,.13f)||el(.26f,.01f,.075f,.13f))c=ink;if(el(-.22f,.08f,.025f,.04f)||el(.24f,.08f,.025f,.04f))c=Color.white;if(el(0,-.29f,.13f,.075f))c=ink;
  if(kind==5&&el(0,-.4f,.27f,.18f))c=Hex("54425E");if(el(-.38f,-.2f,.08f,.045f)||el(.38f,-.2f,.08f,.045f))c=Hex("F8B2CF");t.SetPixel(x,y,c);}
 t.Apply();return SaveTexture(new[]{"CandyWalker","GummyJumper","ToffeeChaser","CocoaGuard","FlyingGummy","SugarCannon","KingBubble"}[kind],t);}
}
